begin;
create temporary table enrollment_results(test text);
grant all on enrollment_results to authenticated,anon;
create function pg_temp.denied(label text, statement text) returns void language plpgsql as $$ begin
 begin execute statement; raise exception 'Unexpected success: %',label;
 exception when insufficient_privilege or invalid_parameter_value or serialization_failure then null; end;
 insert into enrollment_results values(label);
end; $$;
grant execute on function pg_temp.denied(text,text) to authenticated,anon;
do $$ declare o uuid; e uuid; s uuid; u uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); begin
 insert into auth.users(id,email) values(u,'enrollment-'||u||'@example.test'),(other,'enrollment-'||other||'@example.test');
 update public.profiles set first_name='Texas',last_name='Player' where id=u;
 insert into public.organizations(name,slug) values('Texas enrollment test','enrollment-'||gen_random_uuid()) returning id into o;
 select id into s from public.sports where active limit 1;
 insert into public.events(organization_id,sport_id,event_name,start_date,end_date,registration_type,status,pricing_model,registration_fee,currency)
 values(o,s,'Dallas Enrollment Test',current_date+30,current_date+31,'BOTH','PUBLISHED','PER_PLAYER',25,'USD') returning id into e;
 perform set_config('test.enrollment_event',e::text,true);
 perform set_config('test.enrollment_player',u::text,true);
 perform set_config('test.enrollment_other',other::text,true);
end; $$;
select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true);
set local role authenticated;
select pg_temp.denied('player cannot open registration',format('select public.enrollment_action(%L,''window'',''{"status":"REGISTRATION_OPEN"}'')',current_setting('test.enrollment_event')));
select pg_temp.denied('team creation requires registration open',format('select public.enrollment_action(%L,''create_team'',''{"name":"Austin Aces"}'')',current_setting('test.enrollment_event')));
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'publish_waiver','{"title":"Texas test waiver","text":"Test-only waiver text for transactional verification. Not a real legal agreement."}');
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'window','{"status":"REGISTRATION_OPEN"}');
insert into enrollment_results values('organizer publishes waiver and opens registration');
reset role;
select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true);
set local role authenticated;
select set_config('test.enrollment_team',public.enrollment_action(current_setting('test.enrollment_event')::uuid,'create_team','{"name":"Austin Aces"}')::text,true);
insert into enrollment_results values('player creates team and becomes captain without privileged role');
select pg_temp.denied('invalid team name rejected',format('select public.enrollment_action(%L,''create_team'',''{"name":"A"}'')',current_setting('test.enrollment_event')));
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'invite',jsonb_build_object('team_id',current_setting('test.enrollment_team'),'user_id',current_setting('test.enrollment_player')));
insert into enrollment_results values('captain invites player with pending consent');
select pg_temp.denied('captain cannot directly accept for another player',format('update public.team_members set invitation_status=''ACCEPTED'' where team_id=%L',current_setting('test.enrollment_team')));
select pg_temp.denied('captain cannot use response API for another player',format('select public.enrollment_action(%L,''respond'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'),'user_id',current_setting('test.enrollment_player'),'status','ACCEPTED')));
select pg_temp.denied('missing waiver prevents submission',format('select public.enrollment_action(%L,''submit'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'))));
select pg_temp.denied('legacy direct submission also requires waiver',format('insert into public.registrations(event_id,user_id,registration_type,registration_status) values(%L,auth.uid(),''INDIVIDUAL'',''SUBMITTED'')',current_setting('test.enrollment_event')));
select set_config('test.enrollment_waiver',(public.get_enrollment(current_setting('test.enrollment_event')::uuid)->'waivers'->0->>'id'),true);
select pg_temp.denied('direct waiver forgery denied',format('insert into public.waiver_acceptances(waiver_id,user_id,accepted_at) values(%L,auth.uid(),''2000-01-01'')',current_setting('test.enrollment_waiver')));
select pg_temp.denied('stale waiver version denied',format('select public.enrollment_action(%L,''accept_waiver'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('waiver_id',current_setting('test.enrollment_waiver'),'version',99,'accepted',true)));
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'accept_waiver',jsonb_build_object('waiver_id',current_setting('test.enrollment_waiver'),'version',1,'accepted',true));
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.enrollment_other'),true);
set local role authenticated;
do $$ begin
 if jsonb_array_length(public.get_enrollment(current_setting('test.enrollment_event')::uuid)->'teams')<>0 then raise exception 'Roster leaked'; end if;
 insert into enrollment_results values('unrelated user cannot read enrollment roster');
 if exists(select 1 from public.team_members where team_id=current_setting('test.enrollment_team')::uuid) then raise exception 'Direct roster read leaked'; end if;
 insert into enrollment_results values('unrelated direct roster read is filtered');
end; $$;
select pg_temp.denied('unrelated user cannot invite',format('select public.enrollment_action(%L,''invite'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'),'user_id',current_setting('test.enrollment_other'))));
select pg_temp.denied('unrelated user cannot submit team',format('select public.enrollment_action(%L,''submit'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'))));
select pg_temp.denied('player cannot publish legal text',format('select public.enrollment_action(%L,''publish_waiver'',''{"title":"Forged text","text":"Unauthorized waiver text must be rejected by the server."}'')',current_setting('test.enrollment_event')));
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.enrollment_player'),true);
set local role authenticated;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'respond',jsonb_build_object('team_id',current_setting('test.enrollment_team'),'status','ACCEPTED'));
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'accept_waiver',jsonb_build_object('waiver_id',current_setting('test.enrollment_waiver'),'version',1,'accepted',true));
insert into enrollment_results values('invited player accepts own invitation and waiver');
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'accept_waiver',jsonb_build_object('waiver_id',current_setting('test.enrollment_waiver'),'version',1,'accepted',true));
do $$ begin
 if (select count(*) from public.waiver_acceptances where waiver_id=current_setting('test.enrollment_waiver')::uuid and user_id=auth.uid())<>1 then raise exception 'Acceptance duplicated'; end if;
 insert into enrollment_results values('waiver acceptance retry is idempotent');
end; $$;
select pg_temp.denied('waiver text cannot be edited directly',format('update public.waivers set waiver_text=''changed'' where id=%L',current_setting('test.enrollment_waiver')));
reset role;
select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true);
set local role authenticated;
select set_config('test.enrollment_reg',public.enrollment_action(current_setting('test.enrollment_event')::uuid,'submit',jsonb_build_object('team_id',current_setting('test.enrollment_team'),'amount_due',0,'payment_status','PAID'))::text,true);
do $$ declare r public.registrations; begin
 select * into strict r from public.registrations where id=current_setting('test.enrollment_reg')::uuid;
 if r.amount_due<>50 or r.payment_status<>'PENDING' or r.amount_paid<>0 or r.waiver_status<>'ACCEPTED' then raise exception 'Fee or consent derivation failed'; end if;
 if not (public.get_enrollment(r.event_id)->'teams'->0->>'locked')::boolean then raise exception 'Roster not locked'; end if;
 insert into enrollment_results values('submission derives two-player fee and locks roster');
end; $$;
select pg_temp.denied('submitted roster cannot change',format('select public.enrollment_action(%L,''remove'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'),'user_id',current_setting('test.enrollment_player'))));
select pg_temp.denied('duplicate submission rejected',format('select public.enrollment_action(%L,''submit'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('team_id',current_setting('test.enrollment_team'))));
select pg_temp.denied('captain cannot reopen roster',format('select public.enrollment_action(%L,''review'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('registration_id',current_setting('test.enrollment_reg'),'status','DRAFT')));
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select pg_temp.denied('stale organizer review rejected',format('select public.enrollment_action(%L,''review'',%L::jsonb)',current_setting('test.enrollment_event'),jsonb_build_object('registration_id',current_setting('test.enrollment_reg'),'status','APPROVED','expected_updated_at','2000-01-01')));
select pg_temp.denied('waiver publication after submission rejected',format('select public.enrollment_action(%L,''publish_waiver'',''{"title":"New waiver","text":"A new test waiver text that must not replace submitted consent."}'')',current_setting('test.enrollment_event')));
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'review',jsonb_build_object('registration_id',r.id,'status','DRAFT','expected_updated_at',r.updated_at)) from public.registrations r where id=current_setting('test.enrollment_reg')::uuid;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'remove',jsonb_build_object('team_id',current_setting('test.enrollment_team'),'user_id',current_setting('test.enrollment_player')));
insert into enrollment_results values('organizer reopens unpaid registration and changes roster');
reset role;
select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true);
set local role authenticated;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'submit',jsonb_build_object('team_id',current_setting('test.enrollment_team')));
do $$ begin
 if (select amount_due from public.registrations where id=current_setting('test.enrollment_reg')::uuid)<>25 then raise exception 'Resubmission not repriced'; end if;
 insert into enrollment_results values('resubmission reprices accepted roster and locks again');
end; $$;
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'review',jsonb_build_object('registration_id',r.id,'status','APPROVED','expected_updated_at',r.updated_at)) from public.registrations r where id=current_setting('test.enrollment_reg')::uuid;
do $$ begin
 if not exists(select 1 from public.registrations where id=current_setting('test.enrollment_reg')::uuid and registration_status='APPROVED' and payment_status='PENDING') then raise exception 'Approval altered payment'; end if;
 insert into enrollment_results values('organizer approval does not mark payment paid');
end; $$;
reset role;
update public.registrations set amount_paid=25,payment_status='PAID' where id=current_setting('test.enrollment_reg')::uuid;
set local role authenticated;
select pg_temp.denied('paid registration cannot be reopened',format('select public.enrollment_action(%L,''review'',%L::jsonb)',current_setting('test.enrollment_event'),(select jsonb_build_object('registration_id',id,'status','DRAFT','expected_updated_at',updated_at) from public.registrations where id=current_setting('test.enrollment_reg')::uuid)));
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.enrollment_player'),true);
set local role authenticated;
select public.enrollment_action(current_setting('test.enrollment_event')::uuid,'submit','{}');
insert into enrollment_results values('individual can submit own registration with accepted waiver');
reset role;
update public.profiles set account_status='SUSPENDED' where id=current_setting('test.enrollment_player')::uuid;
set local role authenticated;
select pg_temp.denied('suspended account cannot read enrollment',format('select public.get_enrollment(%L)',current_setting('test.enrollment_event')));
select pg_temp.denied('suspended account cannot write enrollment',format('select public.enrollment_action(%L,''submit'',''{}'')',current_setting('test.enrollment_event')));
reset role;
set local role anon;
select pg_temp.denied('anonymous cannot access enrollment',format('select public.get_enrollment(%L)',current_setting('test.enrollment_event')));
select pg_temp.denied('anonymous cannot execute enrollment writes',format('select public.enrollment_action(%L,''submit'',''{}'')',current_setting('test.enrollment_event')));
reset role;
do $$ begin
 if not exists(select 1 from arenax_private.enrollment_audit where event_id=current_setting('test.enrollment_event')::uuid and action='review:DRAFT') then raise exception 'Reopening not audited'; end if;
 insert into enrollment_results values('organizer reopening leaves server audit');
end; $$;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(test order by test)) as verification from enrollment_results;
rollback;
